## Đề bài
Một số Armstrong là số n có d chữ số thoả n = a_1^d + a_2^d + ... + a_d^d,
với a_i là chữ số thứ i của n (luỹ thừa bậc d = số chữ số của n, KHÔNG phải luôn là bậc 3).
Ví dụ 1634 có 4 chữ số và 1^4 + 6^4 + 3^4 + 4^4 = 1634 nên là số Armstrong.

Input: một số nguyên n (1 <= n <= 10^9).
Output: in "True" nếu n là số Armstrong, ngược lại in "False".

| Input | Output |
|---|---|
| 1634 | True |
| 123 | False |

Lưu ý: không được dùng hàm pow.

## Code sinh viên
```cpp
#include <iostream>
using namespace std;

// Kiem tra so Armstrong
int demChuSo(int x) {
    int dem = 0;
    if (x == 0) {
        dem = 1;
    } else {
        while (true) {
        if (!(x != 0)) break;
            x = x / 10;
            dem = dem + 1;
        }
    }
    return dem;
}

long long gt(int chiSo, int bien) {
    long long kq = 1;
    int i = 1;
    while (i <= bien) {
        kq = kq * chiSo;
        i = i + 1;
    }
    return kq;
}

int main() {
    int n;
    cin >> n;
    int soChuSo = demChuSo(n);
    int tam = n;
    long long tong = 0;
    while (tam > 0) {
        int chuSo = tam % 10;
        long long giaTri = gt(chuSo, soChuSo);
        tong = tong + giaTri;
        tam = tam / 10;
    }
    if (tong == n) {
        cout << "True";
    } else {
        cout << "False";
    }
    return 0;
}
```

