## Đề bài
Một số Armstrong là số n có d chữ số thoả n = a_1^d + a_2^d + ... + a_d^d,
với a_i là chữ số thứ i của n (luỹ thừa bậc d = số chữ số của n, KHÔNG phải luôn là bậc 3).
Ví dụ 1634 có 4 chữ số và 1^4 + 6^4 + 3^4 + 4^4 = 1634 nên là số Armstrong.

Input: một số nguyên n (1 <= n <= 10^9).
Output: in "True" nếu n là số Armstrong, ngược lại in "False".

| Input | Output |
|---|---|
| 1634 | True |
| 123 | False |

Lưu ý: không được dùng hàm pow.

## Code sinh viên
```cpp
#include <iostream>
using namespace std;

// Kiem tra so Armstrong
int x5(int x) {
    int x1 = 0;
    if (x == 0) {
        x1 = 1;
    } else {
        while (x != 0) {
            x = x / 10;
            x1 = x1 + 1;
        }
    }
    return x1;
}

long long luyThua(int coSo, int soMu) {
    long long x3 = 1;
    int i = 1;
    while (i <= soMu) {
        x3 = x3 * coSo;
        i = i + 1;
    }
    return x3;
}

int main() {
    int n;
    cin >> n;
    int soChuSo = x5(n);
    int x2 = n;
    long long x4 = 0;
    while (x2 > 0) {
        int chuSo = x2 % 10;
        long long giaTri = luyThua(chuSo, soChuSo);
        x4 = x4 + giaTri;
        x2 = x2 / 10;
    }
    if (x4 == n) {
        cout << "True";
    } else {
        cout << "False";
    }
    return 0;
}

