    while (b--) r *= a;
    return r;
}

int main() {
    ll n; cin >> n;
    string s = to_string(n);
    int d = s.size();
    ll sum = 0;
    for (char c : s) sum += mu(c + '0', d);
    cout << (sum == n ? "True" : "False");
    return 0;
}
