using namespace std;

// tinh a mu k
int luyThua(int a, int k)
{
    int kq = a;
    for (int i = 1; i < k; i++)
    {
        int kq = kq * a;
    }
    return kq;
}

int demChuSo(int n)
{
    if (n == 0) return 1;
    int dem = 0;
    while (n > 0)
    {
        dem++;
        n = n / 10;
    }
    return dem;
}

int main()
{
    int n;
    cin >> n;
    int soChuSo = demChuSo(n);
    int tong = 0;
    int tam = n;
    while (tam > 0)
    {
        tong = tong + luyThua(tam % 10, soChuSo);
        tam = tam / 10;
    }
    if (tong == n)
        cout << "True";
    else
        cout << "False";
    return 0;
}
