    string name, nationality;
    Date born, death;
    int total_known_battles;
    string* known_battles;
};
struct Node {
    General general;
    Node* next;
};
General* prob1(string filename, int& n){
    ifstream fin;
    fin.open("filename");
    if(!fin.is_open()) cout<<"error";
    General* a = new  General[n] ;
    string buffer;
    int i=0;
    while(getline(fin,buffer,'\n')){
        General b;
        getline(fin,buffer,',');
        b.name=buffer;

        getline(fin,buffer,',');
        b.nationality=buffer;

        getline(fin,buffer,'-');
        b.born.day=stoi(buffer);

        getline(fin,buffer,'-');
        b.born.month=stoi(buffer);

        getline(fin,buffer,',');
        b.born.year=stoi(buffer);

        getline(fin,buffer,'-');
        b.death.day=stoi(buffer);
        getline(fin,buffer,'-');
        b.death.month=stoi(buffer);
        getline(fin,buffer,' ');
        b.death.year=stoi(buffer);
        getline(fin,buffer,',');
        b.death.era=buffer;
        string b1,b2, b3;
        getline(fin,buffer,',');
        b1=buffer;
        getline(fin,buffer,',');
        b2=buffer;
        getline(fin,buffer,',');
        b3=buffer;
        getline(fin,buffer,'\n');
        b.total_known_battles=stoi(buffer);

